export default function () {
  return (
    <>
    <Button click={() => {alert("wow")}} value="button"/>
    <button onClick={(e) => {alert("real"); e.stopPropagation()}}>anjass</button>
    </>
  );
}

function Button({click, value}) {return <button onClick={click}>{value}</button>}
